/* kn_rx_kat_runner.h — shared KNOWN-ANSWER battery runner for kn_rx.
 *
 * Consumed by BOTH:
 *   - streamer/tests/test_knrx.c   (host/target unit suite; verbose)
 *   - streamer/src/kn_selftest.c   (the §7.9 "rx.vectors" self-test that
 *     re-runs the battery from the SHIPPED binary; silent — knvstd's
 *     stdout is a JSON-lines contract, so verbose must stay 0 there)
 *
 * Vectors: streamer/src/kn_rx_kat_vectors.h, generated by
 * tools/rx_reference.py (independent Python port of nvst.rs @ a49b124;
 * the generator self-proves against goldens transcribed from the
 * reference's own Rust tests before emitting — see docs/RX.md).
 *
 * All functions are static; every section accumulates (checks, failures)
 * into a kn_rx_tally and records the first failing vector name. Nothing
 * aborts on failure — the battery always runs to the end (the "execute as
 * much as possible" test contract, user instruction 2026-10-24).
 */
#ifndef KN_RX_KAT_RUNNER_H
#define KN_RX_KAT_RUNNER_H

#include "kn/kn_rx.h"
#include "kn/kn_gs.h"
#include "kn/knfec.h"
#include "kn/knsrtp.h"
#include "kn/kn_sha1.h"
#include "kn_rx_kat_vectors.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct kn_rx_tally {
    int  checks;
    int  failures;
    char first_fail[96];
} kn_rx_tally;

#define RXT(t, cond, name)                                                \
    do {                                                                  \
        (t)->checks++;                                                    \
        if (!(cond)) {                                                    \
            (t)->failures++;                                              \
            if (!(t)->first_fail[0]) {                                    \
                size_t n_ = strlen(name);                                 \
                if (n_ >= sizeof (t)->first_fail)                         \
                    n_ = sizeof (t)->first_fail - 1;                      \
                memcpy((t)->first_fail, (name), n_);                      \
                (t)->first_fail[n_] = '\0';                               \
            }                                                             \
            if (rxt_verbose)                                              \
                printf("RXKAT FAIL %s:%d: %s\n", __FILE__, __LINE__,      \
                       (name));                                           \
        }                                                                 \
    } while (0)

/* The macro needs the flag in scope; sections take it as a parameter and
 * expose it through this file-static (single-threaded test context). */
static int rxt_verbose = 0;

/* ------------------------------------------------------- packet builders
 * (byte-exact mirrors of tools/rx_reference.py — a second, independent
 * encoder in C; an offset/endianness mistake cannot survive both) */

static uint32_t rxt_xorshift(uint32_t x)
{
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    return x;
}

static void rxt_body(uint8_t *out, uint32_t seed, uint32_t n)
{
    uint32_t x = seed | 1u, i;
    for (i = 0; i < n; ++i) {
        x = rxt_xorshift(x);
        out[i] = (uint8_t)((x & 0xFFu) | 1u);   /* odd: no accidental
                                                   Annex-B start codes */
    }
}

static size_t rxt_media(uint8_t *out, int gs_wire, unsigned nal_type,
                        uint32_t seed, uint32_t blen, int aud)
{
    size_t o = 0;
    if (gs_wire >= 0) {
        out[o++] = 0x47; out[o++] = 0x53; out[o++] = 0x00;
        out[o++] = (uint8_t)(gs_wire & 0xFF);
    }
    out[o++] = 0x00; out[o++] = 0x00; out[o++] = 0x01;
    out[o++] = (uint8_t)(nal_type & 0xFF);
    rxt_body(out + o, seed, blen);
    o += blen;
    if (aud) {
        out[o++] = 0x00; out[o++] = 0x00; out[o++] = 0x01;
        out[o++] = 0x09; out[o++] = 0xF0;
    }
    return o;
}

static void rxt_le32(uint8_t *p, uint32_t v)
{
    p[0] = (uint8_t)v; p[1] = (uint8_t)(v >> 8);
    p[2] = (uint8_t)(v >> 16); p[3] = (uint8_t)(v >> 24);
}

static void rxt_be32(uint8_t *p, uint32_t v)
{
    p[3] = (uint8_t)v; p[2] = (uint8_t)(v >> 8);
    p[1] = (uint8_t)(v >> 16); p[0] = (uint8_t)(v >> 24);
}

static size_t rxt_pkt(uint8_t *out, const kn_rx_kat_step *st,
                      const uint8_t *media, size_t media_len)
{
    size_t o = 0;
    uint32_t packet_word, flags_word, fec_word;
    out[o++] = 0x90u;                                  /* V2 + X */
    out[o++] = (uint8_t)(((st->marker & 1u) << 7) | (st->pt & 0x7Fu));
    out[o++] = (uint8_t)(st->seq >> 8);
    out[o++] = (uint8_t)(st->seq & 0xFFu);
    rxt_be32(out + o, st->ts); o += 4;
    rxt_be32(out + o, st->ssrc); o += 4;
    out[o++] = 0x47; out[o++] = 0x53;                  /* profile BE16 */
    out[o++] = 0x00; out[o++] = 0x04;                  /* words = 4 */
    packet_word = ((st->spi & KN_GS_INDEX_MASK) << 8);
    rxt_le32(out + o, packet_word); o += 4;
    rxt_le32(out + o, st->fi); o += 4;
    flags_word = (st->flags & 0x0Fu)
               | (((st->last & 3u) << 6 | (st->cur & 3u) << 4) << 24);
    rxt_le32(out + o, flags_word); o += 4;
    fec_word = ((st->pct & 0xFFu) << 4) | ((st->fidx & 0x3FFu) << 12)
             | ((st->fsrc & 0x3FFu) << 22);
    rxt_le32(out + o, fec_word); o += 4;
    if (media_len) { memcpy(out + o, media, media_len); o += media_len; }
    return o;
}

static unsigned rxt_parity_count(unsigned d, unsigned pct)
{
    return (d * pct + 99u) / 100u;                     /* div_ceil */
}

/* Canonical GFN-compatible parity packet: Cauchy fold over the zero-padded
 * DATA packets, then the transport envelope + the three authenticated
 * layout fields replaced (ext[0..4] spi and ext[8..11] flags stay ALGEBRAIC
 * so a recovered shard reconstructs them exactly — the reason the reference
 * re-wrap patches only envelope/frame_index/ext11 and never validates the
 * recovered fec_word; nvst.rs:4055-4106, docs/RX.md §Parity). */
static size_t rxt_parity(uint8_t *out, const kn_rx_kat_step *st,
                         uint8_t *const *ref_pkts, const size_t *ref_lens,
                         uint32_t shard_len)
{
    uint32_t npar = rxt_parity_count(st->d_shards, st->pct);
    uint32_t i;
    uint8_t *pad;
    uint32_t fec_word;
    if (!npar || !shard_len) return 0;
    pad = (uint8_t *)malloc(shard_len);
    if (!pad) return 0;
    memset(out, 0, shard_len);
    for (i = 0; i < st->d_shards && (int)i < st->n_refs; ++i) {
        uint8_t coeff = 0;
        memset(pad, 0, shard_len);
        memcpy(pad, ref_pkts[i],
               ref_lens[i] < shard_len ? ref_lens[i] : shard_len);
        if (kn_fec_cauchy_coeff(i, st->p_idx, npar, &coeff) != 0) {
            free(pad);
            return 0;
        }
        kn_gf_axpy(out, pad, shard_len, coeff);
    }
    free(pad);
    out[0] = 0x90u;
    out[1] = (uint8_t)(st->pt & 0x7Fu);
    out[2] = (uint8_t)(st->seq >> 8);
    out[3] = (uint8_t)(st->seq & 0xFFu);
    rxt_be32(out + 4, st->ts);
    rxt_be32(out + 8, st->ssrc);
    out[12] = 0x47; out[13] = 0x53; out[14] = 0x00; out[15] = 0x04;
    rxt_le32(out + 20, st->fi);
    out[27] = (uint8_t)(((st->last & 3u) << 6) | ((st->cur & 3u) << 4));
    fec_word = ((st->pct & 0xFFu) << 4)
             | (((st->d_shards + st->p_idx) & 0x3FFu) << 12)
             | ((st->d_shards & 0x3FFu) << 22);
    rxt_le32(out + 28, fec_word);
    return shard_len;
}

static uint64_t rxt_frame_hash(const uint8_t *b, size_t len)
{
    uint8_t d[KN_SHA1_DIGEST_LEN];
    uint64_t h = 0;
    int i;
    kn_sha1(b, len, d);
    for (i = 0; i < 8; ++i) h = (h << 8) | (uint64_t)d[i];
    return h;
}

static const uint8_t *rxt_blob(int off)
{
    return (off >= 0 && (size_t)off < K_RX_BLOB_LEN) ? &k_rx_blob[off]
                                                     : NULL;
}

/* ------------------------------------------------- section 1: encoders */

static void kn_rx_kat_encoders(kn_rx_tally *t)
{
    int i;
    static uint8_t out[700];

    for (i = 0; i < K_RX_NACKV2_N; ++i) {
        const kn_rx_kat_nackv2 *v = &k_rx_nackv2[i];
        const uint16_t *missing = (v->n > 0) ? &k_rx_miss[v->miss_off] : NULL;
        int rc = kn_rx_ctrl_nack_v2((uint8_t)v->stream, missing,
                                    (uint32_t)v->n, out, sizeof out);
        if (v->exp_len == 0) {
            RXT(t, rc == 0, v->name);
        } else {
            RXT(t, rc == v->exp_len &&
                   memcmp(out, rxt_blob(v->exp_off), (size_t)rc) == 0,
                v->name);
        }
        if (v->exp_len > 1) {
            rc = kn_rx_ctrl_nack_v2((uint8_t)v->stream, missing,
                                    (uint32_t)v->n, out, 4);
            RXT(t, rc == -1, "nack_v2 tight buffer");
        }
    }
    for (i = 0; i < K_RX_RTCP_NACKS_N; ++i) {
        const kn_rx_kat_rtcp_nack *v = &k_rx_rtcp_nacks[i];
        size_t n = kn_rx_rtcp_nack(0x01020304u, 0x05060708u, v->first,
                                   v->last, out, sizeof out);
        RXT(t, n == (size_t)v->exp_len &&
               memcmp(out, rxt_blob(v->exp_off), n) == 0, v->name);
        n = kn_rx_rtcp_nack(1, 2, v->first, v->last, out, 4);
        RXT(t, n == 0, "rtcp nack tight buffer");
    }
    {
        uint8_t pli[12];
        kn_rx_rtcp_pli(0x01020304u, 0x05060708u, pli);
        RXT(t, memcmp(pli, rxt_blob(K_RX_RTCP_PLI_OFF), 12) == 0,
            "rtcp pli golden");
    }
    for (i = 0; i < K_RX_CTRLS_N; ++i) {
        const kn_rx_kat_ctrl *v = &k_rx_ctrls[i];
        int rc = -999;
        double d;
        uint64_t fbits = v->fbits;
        memcpy(&d, &fbits, sizeof d);
        switch (v->kind) {
        case 0:
            rc = kn_rx_ctrl_idr_request(out);
            break;
        case 1:
            rc = kn_rx_ctrl_frame_invalidation(v->args[0], v->args[1],
                                               (uint16_t)v->args[2], out);
            break;
        case 2:
            rc = kn_rx_ctrl_frame_ack((uint32_t)v->args[0],
                                      v->have_f ? &d : NULL,
                                      (uint32_t)v->args[1], out);
            break;
        case 3:
            rc = kn_rx_ctrl_frame_pacing((uint32_t)v->args[0],
                                         (uint32_t)v->args[1],
                                         (uint32_t)v->args[2], out);
            break;
        case 4: {
            kn_rx_qos q;
            memset(&q, 0, sizeof q);
            q.sequence = (uint32_t)v->args[0];
            q.sender_frame_number = (uint32_t)v->args[1];
            q.bw_minimum_server_time = (uint32_t)v->args[2];
            q.bw_queue_delay_us = (uint32_t)v->args[3];
            q.bw_jitter_us = (uint16_t)v->args[4];
            q.loss_per_ten_thousand = (uint16_t)v->args[5];
            q.bw_utilization_percent = (uint8_t)v->args[6];
            q.client_time_90khz = (uint32_t)v->args[7];
            q.bw_lossy_frames = (uint32_t)v->args[8];
            q.bw_estimate_kbps = (uint32_t)v->args[9];
            q.bw_median_server_time = (uint32_t)v->args[10];
            rc = kn_rx_ctrl_qos_report(&q, out);
            break;
        }
        default:
            break;
        }
        RXT(t, rc == v->exp_len &&
               memcmp(out, rxt_blob(v->exp_off), (size_t)v->exp_len) == 0,
            v->name);
    }
}

/* --------------------------------------------- section 2: NACK op script */

static void kn_rx_kat_nack_ops(kn_rx_tally *t)
{
    kn_rx_nack_entry *table =
        (kn_rx_nack_entry *)calloc(KN_RX_NACK_MAX_PENDING, sizeof *table);
    kn_rx_nack n;
    int i;
    if (!table) { RXT(t, 0, "nack table alloc"); return; }
    RXT(t, kn_rx_nack_init(&n, table, 4) == KN_RX_OK, "nack init cap4");

    for (i = 0; i < K_RX_NACK_OPS_N; ++i) {
        const kn_rx_kat_nack_op *o = &k_rx_nack_ops[i];
        char label[64];
        int kf = 0, have = 0;
        uint64_t first = 0, last = 0;
        sprintf(label, "nack op %d (op=%d)", i, o->op);
        switch (o->op) {
        case 0:
            kn_rx_nack_request(&n, o->a, o->b, o->now, &kf);
            break;
        case 1:
            have = kn_rx_nack_take(&n, o->now, o->rtt, &first, &last);
            break;
        case 2:
            have = kn_rx_nack_resolve(&n, o->a);
            break;
        case 3:
            kn_rx_nack_clear(&n);
            break;
        case 4:
            kn_rx_nack_mark_send_failed(&n, o->a, o->b);
            break;
        case 5: {
            kn_rx_nack n2;
            kn_rx_nack_entry *t2 =
                (kn_rx_nack_entry *)calloc(KN_RX_NACK_MAX_PENDING,
                                           sizeof *t2);
            if (!t2) { RXT(t, 0, "nack op5 alloc"); break; }
            kn_rx_nack_init(&n2, t2, KN_RX_NACK_MAX_PENDING);
            kn_rx_nack_request(&n2, 0, 99, 0, &kf);
            have = kn_rx_nack_take(&n2, 0, 0, &first, &last);
            RXT(t, have == 1 && first == K_RX_NACK_OP5_FIRST &&
                   last == K_RX_NACK_OP5_LAST, "nack 64-batch cap");
            free(t2);
            continue;
        }
        default:
            RXT(t, 0, "unknown nack op");
            continue;
        }
        if (o->op == 0) {
            RXT(t, (o->exp_kf < 0 || kf == o->exp_kf) &&
                   n.count == o->exp_count, label);
        } else if (o->op == 1) {
            RXT(t, have == o->exp_have &&
                   (!have || (first == o->exp_first && last == o->exp_last)),
                label);
        } else if (o->op == 2) {
            RXT(t, have == o->exp_have, label);
        } else {
            RXT(t, n.count == o->exp_count, label);
        }
    }
    free(table);
}

/* --------------------------------------- section 3: invalidation script */

static void kn_rx_kat_inval_ops(kn_rx_tally *t)
{
    kn_rx_inval v;
    int i;
    kn_rx_inval_init(&v);
    for (i = 0; i < K_RX_INVAL_OPS_N; ++i) {
        const kn_rx_kat_inval_op *o = &k_rx_inval_ops[i];
        char label[64];
        int kf = 0, rc = -999, contig = -1;
        uint64_t f = 0, l = 0;
        sprintf(label, "inval op %d (op=%d)", i, o->op);
        switch (o->op) {
        case 0:
            rc = kn_rx_inval_lose(&v, o->now);
            break;
        case 1: {
            kn_rx_frame fr;
            memset(&fr, 0, sizeof fr);
            fr.frame_index = o->fi;
            fr.frame_type_wire = (unsigned)o->wire;
            fr.frame_type_known = o->known;
            fr.frame_type_valid = o->known && o->wire >= 1 && o->wire <= 6;
            fr.keyframe = o->keyframe;
            rc = kn_rx_inval_admit(&v, &fr, o->loss, o->now, &kf);
            contig = fr.contiguous;
            break;
        }
        case 2:
            kn_rx_inval_poll_backstop(&v, o->now, &kf);
            rc = 0;
            break;
        case 3:
            rc = kn_rx_inval_take_rfi(&v, &f, &l);
            break;
        case 4:
            kn_rx_inval_restore_rfi(&v, o->a, o->b);
            rc = 0;
            break;
        case 5:
            kn_rx_inval_record_sent(&v, o->now);
            rc = 0;
            break;
        case 6:
            v.have_unsent = 1;
            v.unsent_first = o->a;
            v.unsent_last = o->b;
            rc = 0;
            break;
        default:
            RXT(t, 0, "unknown inval op");
            continue;
        }
        {
            int ok = 1;
            int64_t pf = v.have_pending ? (int64_t)v.pending_first : -1;
            int64_t pl = v.have_pending ? (int64_t)v.pending_last : -1;
            int64_t uf = v.have_unsent ? (int64_t)v.unsent_first : -1;
            int64_t ul = v.have_unsent ? (int64_t)v.unsent_last : -1;
            if (o->op == 0 || o->op == 1 || o->op == 3) {
                if (rc != o->exp_rc) ok = 0;
            }
            if (o->op == 1 && o->exp_contig >= 0 && contig != o->exp_contig)
                ok = 0;
            if (o->op == 2 && kf != o->exp_kf) ok = 0;
            if (o->op == 3 && o->exp_rc &&
                ((int64_t)f != o->exp_ufirst || (int64_t)l != o->exp_ulast))
                ok = 0;
            if (o->op != 3 && o->op != 6) {
                if (pf != o->exp_pfirst || pl != o->exp_plast) ok = 0;
                if (uf != o->exp_ufirst || ul != o->exp_ulast) ok = 0;
            }
            if ((v.have_active_since ? 1 : 0) != o->exp_active) ok = 0;
            if (v.cnt_dropped_frames != o->exp_dropped) ok = 0;
            if (v.cnt_recovered_i != o->exp_rec_i) ok = 0;
            if (v.cnt_idr_backstops != o->exp_backstops) ok = 0;
            RXT(t, ok, label);
            if (!ok && rxt_verbose) {
                printf("  got rc=%d contig=%d kf=%d pend=(%lld,%lld) "
                       "unsent=(%lld,%lld) active=%d dropped=%llu "
                       "rec_i=%llu backstops=%llu\n",
                       rc, contig, kf, (long long)pf, (long long)pl,
                       (long long)uf, (long long)ul, v.have_active_since,
                       (unsigned long long)v.cnt_dropped_frames,
                       (unsigned long long)v.cnt_recovered_i,
                       (unsigned long long)v.cnt_idr_backstops);
            }
        }
    }
}

/* ------------------------------------------- section 4: SRTP vectors */

static void kn_rx_kat_srtp_vecs(kn_rx_tally *t)
{
    int i;
    int backend = kn_srtp_backend_gcm() && kn_srtp_backend_256();
    for (i = 0; i < K_RX_SRTP_VECS_N; ++i) {
        const kn_rx_kat_srtp *v = &k_rx_srtp_vecs[i];
        kn_rx_srtp_session s;
        static uint8_t dgram[512];
        uint64_t index = 0;
        kn_gs_rtp rtp;
        size_t plain_len = 0;
        int detail = 0, rc;
        char label[96];
        int needs_backend = (v->profile != 1);

        sprintf(label, "srtp %s derive", v->name);
        rc = kn_rx_srtp_session_init(&s, v->profile, rxt_blob(v->master_off),
                                     (size_t)v->master_len,
                                     rxt_blob(v->salt_off),
                                     (size_t)v->salt_len,
                                     (size_t)v->tag_len);
        if (needs_backend && !backend) {
            RXT(t, rc == KN_RX_ERR_NO_CIPHER,
                "srtp no-backend honest refusal");
            continue;
        }
        RXT(t, rc == KN_RX_OK, label);
        if (rc != KN_RX_OK) continue;

        RXT(t, memcmp(s.enc_key, rxt_blob(v->enc_off),
                      (size_t)v->enc_len) == 0, "srtp enc key KAT");
        if (v->auth_len > 0)
            RXT(t, memcmp(s.auth_key, rxt_blob(v->auth_off),
                          (size_t)v->auth_len) == 0, "srtp auth key KAT");
        RXT(t, memcmp(s.salt, rxt_blob(v->dsalt_off),
                      (size_t)v->dsalt_len) == 0, "srtp salt KAT");

        sprintf(label, "srtp %s unprotect", v->name);
        if ((size_t)v->dgram_len > sizeof dgram) { RXT(t, 0, label); continue; }
        memcpy(dgram, rxt_blob(v->dgram_off), (size_t)v->dgram_len);
        rc = kn_rx_srtp_unprotect(&s, dgram, (size_t)v->dgram_len, &index,
                                  &rtp, &plain_len, &detail);
        RXT(t, rc == KN_RX_OK && index == v->index &&
               plain_len == (size_t)v->plain_len &&
               memcmp(dgram, rxt_blob(v->plain_off), plain_len) == 0, label);

        memcpy(dgram, rxt_blob(v->dgram_off), (size_t)v->dgram_len);
        rc = kn_rx_srtp_unprotect(&s, dgram, (size_t)v->dgram_len, &index,
                                  &rtp, &plain_len, &detail);
        RXT(t, rc == KN_RX_DROP_REPLAY_REJECTED, "srtp replay rejected");

        kn_rx_srtp_session_init(&s, v->profile, rxt_blob(v->master_off),
                                (size_t)v->master_len, rxt_blob(v->salt_off),
                                (size_t)v->salt_len, (size_t)v->tag_len);
        memcpy(dgram, rxt_blob(v->dgram_off), (size_t)v->dgram_len);
        dgram[v->dgram_len - 1] ^= 0x01;
        rc = kn_rx_srtp_unprotect(&s, dgram, (size_t)v->dgram_len, &index,
                                  &rtp, &plain_len, &detail);
        RXT(t, rc == KN_RX_DROP_AUTH_FAILED, "srtp tamper -> auth failed");

        sprintf(label, "srtp %s protect cross-check", v->name);
        if ((size_t)v->plain_len + 16u > sizeof dgram) {
            RXT(t, 0, label);
            continue;
        }
        memcpy(dgram, rxt_blob(v->plain_off), (size_t)v->plain_len);
        kn_rx_srtp_session_init(&s, v->profile, rxt_blob(v->master_off),
                                (size_t)v->master_len, rxt_blob(v->salt_off),
                                (size_t)v->salt_len, (size_t)v->tag_len);
        {
            kn_gs_rtp h;
            uint8_t iv[16];
            if (kn_gs_rtp_parse_hdr(dgram, (size_t)v->plain_len, &h)
                != KN_GS_OK) {
                RXT(t, 0, label);
                continue;
            }
            if (v->profile == 1) {
                rc = kn_srtp_protect_cm_hmac(dgram, (size_t)v->plain_len,
                                             h.payload_off, h.ssrc, v->index,
                                             s.enc_key, s.auth_key, s.salt,
                                             s.tag_len);
                RXT(t, rc == 0 &&
                       memcmp(dgram, rxt_blob(v->dgram_off),
                              (size_t)v->dgram_len) == 0, label);
            } else if (v->profile == 2) {
                size_t auth_len = (size_t)v->plain_len;
                uint8_t mac[20];
                kn_srtp_aes_cm_iv(s.salt, h.ssrc, v->index, iv);
                kn_srtp_aes256_cm_keystream_xor(
                    s.enc_key, iv, 0, dgram + h.payload_off,
                    auth_len - (size_t)h.payload_off);
                kn_srtp_auth_tag(s.auth_key, dgram, auth_len,
                                 (uint32_t)(v->index >> 16), s.tag_len, mac);
                memcpy(dgram + auth_len, mac, s.tag_len);
                RXT(t, memcmp(dgram, rxt_blob(v->dgram_off),
                              (size_t)v->dgram_len) == 0, label);
            } else {
                uint8_t iv12[12];
                uint8_t tag[16];
                kn_srtp_gcm_iv(s.salt, h.ssrc, (uint32_t)(v->index >> 16),
                               (uint16_t)h.seq, iv12);
                rc = kn_srtp_gcm_auth_encrypt(
                    s.enc_key, v->profile == 3 ? 128u : 256u, iv12,
                    dgram, h.payload_off, tag, s.tag_len,
                    dgram + h.payload_off,
                    (size_t)v->plain_len - (size_t)h.payload_off);
                memcpy(dgram + v->plain_len, tag, s.tag_len);
                RXT(t, rc == 0 &&
                       memcmp(dgram, rxt_blob(v->dgram_off),
                              (size_t)v->dgram_len) == 0, label);
            }
        }
    }
}

/* ---------------------------------------------- section 5: scenarios */

typedef struct {
    uint32_t fi, len;
    uint64_t hash;
    int kf, contig, wire, known;
    uint32_t first_spi, ts;
} rxt_frame;

#define RXT_MAX_FRAMES 64

typedef struct {
    rxt_frame frames[RXT_MAX_FRAMES];
    int n;
} rxt_col;

static void rxt_frame_cb(const kn_rx_frame *f, void *ud)
{
    rxt_col *c = (rxt_col *)ud;
    if (c->n >= RXT_MAX_FRAMES) return;
    c->frames[c->n].fi = f->frame_index;
    c->frames[c->n].len = (uint32_t)f->bytes_len;
    c->frames[c->n].hash = rxt_frame_hash(f->bytes, f->bytes_len);
    c->frames[c->n].kf = f->keyframe;
    c->frames[c->n].contig = f->contiguous;
    c->frames[c->n].wire = (int)f->frame_type_wire;
    c->frames[c->n].known = f->frame_type_known;
    c->frames[c->n].first_spi = f->first_stream_packet_index;
    c->frames[c->n].ts = f->timestamp;
    c->n++;
}

typedef struct {
    kn_rx_video v;
    kn_rx_mem mem;
    uint8_t *arena;
    uint8_t **built;
    size_t *built_len;
    uint32_t pkt_cap;
    rxt_col col;
} rxt_harness;

static void rxt_free_h(rxt_harness *h, uint32_t n_steps)
{
    uint32_t i;
    if (!h) return;
    if (h->built) {
        for (i = 0; i < n_steps; ++i)
            free(h->built[i]);
        free(h->built);
        h->built = NULL;
    }
    free(h->built_len);
    h->built_len = NULL;
    free(h->arena);
    h->arena = NULL;
}

static int rxt_run_scenario(const kn_rx_kat_scenario *sc, kn_rx_tally *t)
{
    rxt_harness h;
    kn_rx_video_config cfg;
    uint32_t i, slots, pkt_cap, shard_len, scratch_len;
    size_t arena_need, off;
    int ok = 1;
    char label[128];
    const kn_rx_kat_step *steps = &k_rx_steps[sc->steps_off];

    sprintf(label, "scenario %s", sc->name);
    memset(&h, 0, sizeof h);
    shard_len = sc->vps + KN_RX_FEC_HEADER_ALLOWANCE;
    pkt_cap = shard_len + 64u;
    /* keep every arena region 8-byte aligned (UBSan; structs carry u64) */
    pkt_cap = (pkt_cap + 7u) & ~7u;
    for (i = 0; i < (uint32_t)sc->n_steps; ++i) {
        if (steps[i].kind == KN_RX_KAT_RAW &&
            ((steps[i].blob_len + 16u + 7u) & ~7u) > pkt_cap)
            pkt_cap = (steps[i].blob_len + 16u + 7u) & ~7u;
        if (steps[i].kind == KN_RX_KAT_DATA) {
            uint32_t need = (32u + 4u + 3u + 1u + steps[i].body_len +
                             5u + 16u + 7u) & ~7u;
            if (need > pkt_cap) pkt_cap = need;
        }
    }
    slots = sc->window + 1u + sc->fec_max_blocks * sc->fec_max_shards + 16u;
    scratch_len = ((uint32_t)kn_fec_scratch_bytes(sc->fec_max_shards,
                                                  shard_len) + 4096u + 7u)
                  & ~7u;

    h.pkt_cap = pkt_cap;
    h.built = (uint8_t **)calloc((size_t)sc->n_steps, sizeof(uint8_t *));
    h.built_len = (size_t *)calloc((size_t)sc->n_steps, sizeof(size_t));
    arena_need = (size_t)slots * sizeof(kn_rx_pkt)
               + (size_t)slots * pkt_cap
               + (size_t)(sc->window + 1u) * sizeof(kn_rx_reorder_entry)
               + (size_t)sc->fec_max_blocks * sizeof(kn_rx_fec_block)
               + (size_t)sc->fec_max_blocks * sc->fec_max_shards *
                     sizeof(uint32_t)
               + scratch_len
               + (size_t)sc->nack_capacity * sizeof(kn_rx_nack_entry)
               + sc->au_cap + 16u * sizeof(kn_rx_event);
    h.arena = (uint8_t *)malloc(arena_need);
    if (!h.built || !h.built_len || !h.arena) {
        RXT(t, 0, label);
        rxt_free_h(&h, 0);
        free(h.built); free(h.built_len);
        return 0;
    }
    off = 0;
    h.mem.pool_meta = (kn_rx_pkt *)(void *)(h.arena + off);
    off += (size_t)slots * sizeof(kn_rx_pkt);
    h.mem.pool_bytes = h.arena + off;
    off += (size_t)slots * pkt_cap;
    h.mem.pool_slots = slots;
    h.mem.pool_pkt_cap = pkt_cap;
    h.mem.reorder_map = (kn_rx_reorder_entry *)(void *)(h.arena + off);
    off += (size_t)(sc->window + 1u) * sizeof(kn_rx_reorder_entry);
    h.mem.fec_blocks = (kn_rx_fec_block *)(void *)(h.arena + off);
    off += (size_t)sc->fec_max_blocks * sizeof(kn_rx_fec_block);
    h.mem.fec_shard_arena = (uint32_t *)(void *)(h.arena + off);
    off += (size_t)sc->fec_max_blocks * sc->fec_max_shards * sizeof(uint32_t);
    h.mem.fec_max_blocks = sc->fec_max_blocks;
    h.mem.fec_max_shards = sc->fec_max_shards;
    h.mem.fec_scratch = h.arena + off;
    off += scratch_len;
    h.mem.fec_scratch_len = scratch_len;
    h.mem.nack_table = (kn_rx_nack_entry *)(void *)(h.arena + off);
    off += (size_t)sc->nack_capacity * sizeof(kn_rx_nack_entry);
    h.mem.nack_capacity = sc->nack_capacity;
    h.mem.au_buffer = h.arena + off;
    off += sc->au_cap;
    h.mem.au_buffer_capacity = sc->au_cap;
    h.mem.events = (kn_rx_event *)(void *)(h.arena + off);
    h.mem.events_capacity = 16;

    memset(&cfg, 0, sizeof cfg);
    cfg.codec = sc->codec;
    cfg.reorder_window_packets = sc->window;
    cfg.max_access_unit_bytes = sc->au_cap;
    cfg.video_packet_size = sc->vps;
    cfg.timeout_ms = sc->timeout_ms;
    cfg.startup_timeout_ms = sc->startup_ms;
    cfg.progress_stall_ms = sc->stall_ms;
    cfg.progress_keyframe_grace_ms = sc->grace_ms;
    cfg.have_expected_pt = sc->have_pt;
    cfg.expected_payload_type = sc->pt;
    cfg.have_expected_ssrc = sc->have_ssrc;
    cfg.expected_ssrc = sc->ssrc;

    if (kn_rx_video_init(&h.v, &cfg, &h.mem, 0) != KN_RX_OK) {
        if (rxt_verbose) printf("FAIL scenario %s: init\n", sc->name);
        RXT(t, 0, label);
        rxt_free_h(&h, 0);
        return 0;
    }
    if (sc->srtp_profile) {
        kn_rx_srtp_session s;
        int rc = kn_rx_srtp_session_init(
            &s, sc->srtp_profile, rxt_blob(sc->master_off),
            (size_t)sc->master_len, rxt_blob(sc->salt_off),
            (size_t)sc->salt_len, (size_t)sc->srtp_tag_len);
        if (rc != KN_RX_OK) {
            if (rc == KN_RX_ERR_NO_CIPHER) {
                /* Backend absent in this build — honest skip, NOT a pass
                 * dressed up: the tally records a check that the refusal
                 * was honest, the scenario reports skipped. */
                RXT(t, 1, label);
                if (rxt_verbose)
                    printf("  scenario %s: SRTP backend unavailable in this "
                           "build — skipping honestly\n", sc->name);
                rxt_free_h(&h, 0);
                return 1;
            }
            RXT(t, 0, "scenario srtp init");
            rxt_free_h(&h, 0);
            return 0;
        }
        RXT(t, sc->enc_off < 0 ||
               memcmp(s.enc_key, rxt_blob(sc->enc_off),
                      (size_t)sc->enc_len) == 0,
            "scenario srtp derived enc key");
        kn_rx_video_set_srtp(&h.v, &s);
    }

    for (i = 0; i < (uint32_t)sc->n_steps; ++i) {
        const kn_rx_kat_step *st = &steps[i];
        if (st->kind == KN_RX_KAT_DATA || st->kind == KN_RX_KAT_PARITY ||
            st->kind == KN_RX_KAT_RAW) {
            uint8_t media[512];
            size_t mlen = 0, plen = 0;
            if (st->kind == KN_RX_KAT_DATA) {
                mlen = rxt_media(media, st->gs_wire, st->nal_type,
                                 st->body_seed, st->body_len, st->aud_tail);
                {
                    static uint8_t tmp[2112];
                    plen = rxt_pkt(tmp, st, media, mlen);
                    h.built[i] = (uint8_t *)malloc(plen ? plen : 1);
                    if (h.built[i]) {
                        memcpy(h.built[i], tmp, plen);
                        h.built_len[i] = plen;
                    }
                }
            } else if (st->kind == KN_RX_KAT_PARITY) {
                uint8_t *refs[12];
                size_t reflens[12];
                static uint8_t tmp[2112];
                int k, good = 1;
                if (st->n_refs > 12) good = 0;
                for (k = 0; good && k < st->n_refs; ++k) {
                    int rid = st->refs[k];
                    if (rid < 0 || rid >= (int)i || !h.built[rid]) {
                        good = 0;
                        break;
                    }
                    refs[k] = h.built[rid];
                    reflens[k] = h.built_len[rid];
                }
                if (good) {
                    plen = rxt_parity(tmp, st, refs, reflens, st->shard_len);
                    h.built[i] = (uint8_t *)malloc(plen ? plen : 1);
                    if (h.built[i]) {
                        memcpy(h.built[i], tmp, plen);
                        h.built_len[i] = plen;
                    }
                }
            } else {
                plen = st->blob_len;
                h.built[i] = (uint8_t *)malloc(plen ? plen : 1);
                if (h.built[i]) {
                    memcpy(h.built[i], rxt_blob(st->blob_off), plen);
                    h.built_len[i] = plen;
                }
            }
            if (!h.built[i]) {
                RXT(t, 0, "scenario step build alloc");
                ok = 0;
                break;
            }
        }
    }

    for (i = 0; ok && i < (uint32_t)sc->n_steps; ++i) {
        const kn_rx_kat_step *st = &steps[i];
        const kn_rx_kat_step_exp *ex = &k_rx_exps[sc->steps_off + i];
        static uint8_t work[2112];
        int k2;
        h.col.n = 0;
        switch (st->kind) {
        case KN_RX_KAT_DATA:
        case KN_RX_KAT_PARITY:
            if (st->deliver && h.built_len[i])
                kn_rx_video_process_packet(&h.v, st->index, h.built[i],
                                           h.built_len[i], st->now_ms,
                                           rxt_frame_cb, &h.col);
            break;
        case KN_RX_KAT_RAW:
            if (st->deliver && h.built_len[i]) {
                if (st->via_datagram) {
                    if (h.built_len[i] > sizeof work) {
                        RXT(t, 0, "raw too big");
                        ok = 0;
                        break;
                    }
                    memcpy(work, h.built[i], h.built_len[i]);
                    kn_rx_video_process_datagram(&h.v, work, h.built_len[i],
                                                 st->now_ms, rxt_frame_cb,
                                                 &h.col);
                } else {
                    kn_rx_video_process_packet(&h.v, st->index, h.built[i],
                                               h.built_len[i], st->now_ms,
                                               rxt_frame_cb, &h.col);
                }
            }
            break;
        case KN_RX_KAT_POLL:
            kn_rx_video_poll(&h.v, st->now_ms, rxt_frame_cb, &h.col);
            break;
        case KN_RX_KAT_LIFECYCLE:
            switch (st->op) {
            case KN_RX_KAT_PAUSE:
                kn_rx_video_pause(&h.v, st->now_ms); break;
            case KN_RX_KAT_RESUME:
                kn_rx_video_resume(&h.v, st->now_ms); break;
            case KN_RX_KAT_RECOVER:
                kn_rx_video_recover(&h.v, st->now_ms); break;
            default:
                kn_rx_video_stop(&h.v, st->now_ms); break;
            }
            break;
        case KN_RX_KAT_NACK_TAKE:
        case KN_RX_KAT_KF_TAKE:
        case KN_RX_KAT_RFI_TAKE:
            break;               /* no pipeline call; verified below */
        default:
            RXT(t, 0, "unknown step kind");
            ok = 0;
            break;
        }
        if (!ok) break;

        /* take-steps make no pipeline call: the staged events belong to the
         * previous step (the Python reference records an empty list) */
        if (st->kind != KN_RX_KAT_NACK_TAKE && st->kind != KN_RX_KAT_KF_TAKE &&
            st->kind != KN_RX_KAT_RFI_TAKE) {
            uint32_t n_ev = 0, k;
            const kn_rx_event *evs = kn_rx_video_events(&h.v, &n_ev);
            if ((int)n_ev != ex->n_ev) {
                if (rxt_verbose) {
                    printf("FAIL %s step %d: events %u != %d\n", sc->name, i,
                           n_ev, ex->n_ev);
                    for (k = 0; k < n_ev; ++k)
                        printf("  got[%u]: type=%d reason=%d detail=%d "
                               "idx=%llu gap=(%llu,%llu) idle=%llu "
                               "state=%d\n", k, evs[k].type,
                               evs[k].drop_reason, evs[k].detail,
                               (unsigned long long)evs[k].index,
                               (unsigned long long)evs[k].gap_first,
                               (unsigned long long)evs[k].gap_last,
                               (unsigned long long)evs[k].idle_ms,
                               evs[k].new_state);
                }
                RXT(t, 0, "scenario step event count");
                ok = 0;
                break;
            }
            for (k = 0; k < n_ev; ++k) {
                const kn_rx_kat_ev *we = &k_rx_evs[ex->ev_off + (int)k];
                const kn_rx_event *e = &evs[k];
                int t_ok = (e->type == we->type);
                uint64_t a = 0, b = 0;
                int r_ok = 1;
                switch (we->type) {
                case KN_RX_EV_DROPPED:
                    r_ok = (e->drop_reason == we->reason) &&
                           (we->detail == 0 || e->detail == we->detail);
                    a = e->index;
                    break;
                case KN_RX_EV_RECOVERY_GAP:
                    a = e->gap_first; b = e->gap_last;
                    break;
                case KN_RX_EV_RECOVERY_TIMEOUT:
                    a = e->idle_ms;
                    break;
                case KN_RX_EV_LIFECYCLE:
                    a = (uint64_t)e->new_state;
                    break;
                case KN_RX_EV_PROGRESS_STALL:
                case KN_RX_EV_PROGRESS_RECOVERY:
                    a = e->idle_ms;
                    break;
                default:
                    break;     /* RESUMED: type-only compare */
                }
                if (we->type != KN_RX_EV_PROGRESS_RESUMED) {
                    if (a != we->a || b != we->b) r_ok = 0;
                }
                if (!t_ok || !r_ok) {
                    if (rxt_verbose)
                        printf("FAIL %s step %d ev %u: type %d!=%d reason "
                               "%d!=%d a %llu!=%llu b %llu!=%llu\n",
                               sc->name, i, k, e->type, we->type,
                               e->drop_reason, we->reason,
                               (unsigned long long)a,
                               (unsigned long long)we->a,
                               (unsigned long long)b,
                               (unsigned long long)we->b);
                    RXT(t, 0, "scenario step event");
                    ok = 0;
                    break;
                }
            }
            if (!ok) break;
            if (h.col.n != ex->n_frames) {
                if (rxt_verbose)
                    printf("FAIL %s step %d: frames %d != %d\n", sc->name, i,
                           h.col.n, ex->n_frames);
                RXT(t, 0, "scenario step frame count");
                ok = 0;
                break;
            }
            for (k2 = 0; k2 < ex->n_frames; ++k2) {
                const kn_rx_kat_frame *wf =
                    &k_rx_frames[ex->frames_off + k2];
                const rxt_frame *gf = &h.col.frames[k2];
                int good = gf->fi == wf->frame_index &&
                           gf->len == wf->len && gf->hash == wf->hash &&
                           gf->kf == wf->keyframe &&
                           gf->contig == wf->contiguous &&
                           gf->wire == wf->wire && gf->known == wf->known &&
                           gf->first_spi == wf->first_spi &&
                           gf->ts == wf->ts;
                if (!good) {
                    if (rxt_verbose)
                        printf("FAIL %s step %d frame %d: fi %u/%u len %u/%u "
                               "hash %016llx/%016llx kf %d/%d contig %d/%d "
                               "wire %d/%d known %d/%d spi %u/%u ts %u/%u\n",
                               sc->name, i, k2, gf->fi, wf->frame_index,
                               gf->len, wf->len,
                               (unsigned long long)gf->hash,
                               (unsigned long long)wf->hash,
                               gf->kf, wf->keyframe, gf->contig,
                               wf->contiguous, gf->wire, wf->wire,
                               gf->known, wf->known, gf->first_spi,
                               wf->first_spi, gf->ts, wf->ts);
                    RXT(t, 0, "scenario step frame");
                    ok = 0;
                    break;
                }
            }
            if (!ok) break;
        }
        if (st->kind == KN_RX_KAT_NACK_TAKE) {
            uint64_t f = 0, l = 0;
            int have = kn_rx_nack_take(&h.v.nack, st->now_ms,
                                       (uint32_t)st->op, &f, &l);
            if (have != ex->nack_have ||
                (have && (f != ex->nack_first || l != ex->nack_last))) {
                if (rxt_verbose)
                    printf("FAIL %s step %d: nack take (%d,%llu,%llu) != "
                           "(%d,%llu,%llu)\n", sc->name, i, have,
                           (unsigned long long)f, (unsigned long long)l,
                           ex->nack_have,
                           (unsigned long long)ex->nack_first,
                           (unsigned long long)ex->nack_last);
                RXT(t, 0, "scenario nack take");
                ok = 0;
                break;
            }
        }
        if (st->kind == KN_RX_KAT_KF_TAKE && ex->kf_expect >= 0) {
            int got = kn_rx_video_take_keyframe_request(&h.v);
            if (got != ex->kf_expect) {
                if (rxt_verbose)
                    printf("FAIL %s step %d: kf_take %d != %d\n", sc->name, i,
                           got, ex->kf_expect);
                RXT(t, 0, "scenario kf take");
                ok = 0;
                break;
            }
        }
        if (st->kind == KN_RX_KAT_RFI_TAKE) {
            uint64_t f = 0, l = 0;
            int have = kn_rx_inval_take_rfi(&h.v.inval, &f, &l);
            if (have != ex->rfi_have ||
                (have && (f != ex->rfi_first || l != ex->rfi_last))) {
                if (rxt_verbose)
                    printf("FAIL %s step %d: rfi take (%d,%llu,%llu) != "
                           "(%d,%llu,%llu)\n", sc->name, i, have,
                           (unsigned long long)f, (unsigned long long)l,
                           ex->rfi_have,
                           (unsigned long long)ex->rfi_first,
                           (unsigned long long)ex->rfi_last);
                RXT(t, 0, "scenario rfi take");
                ok = 0;
                break;
            }
        }
        if (ex->state_expect >= 0 && h.v.state != ex->state_expect) {
            if (rxt_verbose)
                printf("FAIL %s step %d: state %d != %d\n", sc->name, i,
                       h.v.state, ex->state_expect);
            RXT(t, 0, "scenario state");
            ok = 0;
            break;
        }
    }

    if (ok) {
        int good = 1;
        if (h.v.authenticated_packets != sc->c_auth) good = 0;
        if (h.v.fec_packets != sc->c_fec_pkts) good = 0;
        if (h.v.fec_repaired_packets != sc->c_fec_rep) good = 0;
        if (h.v.frames_emitted != sc->c_frames) good = 0;
        if (h.v.stale_packets != sc->c_stale) good = 0;
        if (h.v.packet_gap_recoveries != sc->c_gaps) good = 0;
        if (h.v.withheld_frames != sc->c_withheld) good = 0;
        if (h.v.keyframe_requests != sc->c_kf) good = 0;
        if (h.v.recovered_retransmissions != sc->c_retrans) good = 0;
        if (h.v.replay_rejections != sc->c_replay) good = 0;
        if (!good && rxt_verbose) {
            printf("  %s counters: auth %llu/%llu fec %llu/%llu rep %llu/%llu "
                   "frames %llu/%llu stale %llu/%llu gaps %llu/%llu "
                   "withheld %llu/%llu kf %llu/%llu retrans %llu/%llu "
                   "replay %llu/%llu\n", sc->name,
                   (unsigned long long)h.v.authenticated_packets,
                   (unsigned long long)sc->c_auth,
                   (unsigned long long)h.v.fec_packets,
                   (unsigned long long)sc->c_fec_pkts,
                   (unsigned long long)h.v.fec_repaired_packets,
                   (unsigned long long)sc->c_fec_rep,
                   (unsigned long long)h.v.frames_emitted,
                   (unsigned long long)sc->c_frames,
                   (unsigned long long)h.v.stale_packets,
                   (unsigned long long)sc->c_stale,
                   (unsigned long long)h.v.packet_gap_recoveries,
                   (unsigned long long)sc->c_gaps,
                   (unsigned long long)h.v.withheld_frames,
                   (unsigned long long)sc->c_withheld,
                   (unsigned long long)h.v.keyframe_requests,
                   (unsigned long long)sc->c_kf,
                   (unsigned long long)h.v.recovered_retransmissions,
                   (unsigned long long)sc->c_retrans,
                   (unsigned long long)h.v.replay_rejections,
                   (unsigned long long)sc->c_replay);
        }
        RXT(t, good, label);
    }
    rxt_free_h(&h, (uint32_t)sc->n_steps);
    return ok;
}

static void kn_rx_kat_scenarios(kn_rx_tally *t, int *passed, int *total)
{
    int i, p = 0;
    for (i = 0; i < K_RX_SCENARIOS_N; ++i)
        if (rxt_run_scenario(&k_rx_scenarios[i], t))
            p++;
    if (passed) *passed = p;
    if (total) *total = K_RX_SCENARIOS_N;
    if (rxt_verbose)
        printf("  scenarios passed: %d/%d\n", p, K_RX_SCENARIOS_N);
}

/* Run the ENTIRE battery; returns failures. This is the body of both the
 * test suite's vector sections and the rx.vectors self-test. */
static int kn_rx_kat_run_all(kn_rx_tally *t, int verbose,
                             int *scenarios_passed, int *scenarios_total)
{
    rxt_verbose = verbose;
    memset(t, 0, sizeof *t);
    kn_rx_kat_encoders(t);
    kn_rx_kat_nack_ops(t);
    kn_rx_kat_inval_ops(t);
    kn_rx_kat_srtp_vecs(t);
    kn_rx_kat_scenarios(t, scenarios_passed, scenarios_total);
    rxt_verbose = 0;
    return t->failures;
}

#endif /* KN_RX_KAT_RUNNER_H */
